// 1. The Core Abstraction
interface Payable {
    double calculateGrossPay();
    String getPayeeId();
}

// 2. Base Entity (Template Pattern)
abstract class Employee implements Payable {
    private final String id;
    private final String name;
    private final String department;

    public Employee(String id, String name, String department) {
        if (id == null || name == null) throw new IllegalArgumentException("Invalid employee credentials");
        this.id = id;
        this.name = name;
        this.department = department;
    }
    @Override
    public String getPayeeId() { return id; }
    public String getName() { return name; }
    public String getDepartment() { return department; }
}

// 3. Concrete Polymorphic Subclasses
class SalariedEmployee extends Employee {
    private final double monthlySalary;
    public SalariedEmployee(String id, String name, String dept, double monthlySalary) {
        super(id, name, dept);
        this.monthlySalary = monthlySalary;
    }
    @Override
    public double calculateGrossPay() { return monthlySalary; }
}

class HourlyEmployee extends Employee {
    private final double hourlyRate;
    private final double hoursWorked;
    public HourlyEmployee(String id, String name, String dept, double hourlyRate, double hoursWorked) {
        super(id, name, dept);
        this.hourlyRate = hourlyRate;
        this.hoursWorked = hoursWorked;
    }
    @Override
    public double calculateGrossPay() {
        // 1.5x overtime for hours > 40
        if (hoursWorked <= 40) return hoursWorked * hourlyRate;
        return (40 * hourlyRate) + ((hoursWorked - 40) * hourlyRate * 1.5);
    }
}

public class EmployeeHierarchyDemo {
    public static void main(String[] args) {
        Employee emp1 = new SalariedEmployee("E-101", "Munaf", "Engineering", 8000.0);
        Employee emp2 = new HourlyEmployee("E-102", "Keerthana", "Consulting", 50.0, 45.0); // 40*50 + 5*75 = 2375

        System.out.println(emp1.getName() + " Gross: $" + emp1.calculateGrossPay());
        System.out.println(emp2.getName() + " Gross: $" + emp2.calculateGrossPay());
    }
}

