import java.util.ArrayList;
import java.util.List;

// Immutable PaySlip Value Object
class PaySlip {
    private final String employeeId;
    private final double grossPay;
    private final double taxDeduction;
    private final double netPay;

    public PaySlip(String empId, double gross, double tax) {
        this.employeeId = empId;
        this.grossPay = gross;
        this.taxDeduction = tax;
        this.netPay = gross - tax;
    }
    public String getEmployeeId() { return employeeId; }
    public double getGrossPay() { return grossPay; }
    public double getTaxDeduction() { return taxDeduction; }
    public double getNetPay() { return netPay; }
}

// Tax Strategy
interface TaxStrategy {
    double computeTax(double grossAmount);
}

class StandardTaxStrategy implements TaxStrategy {
    @Override
    public double computeTax(double grossAmount) {
        return grossAmount * 0.15; // 15% flat deduction
    }
}

// Department Aggregate
class Department {
    private final String deptName;
    private final List<Employee> staff = new ArrayList<>();
    public Department(String name) { this.deptName = name; }
    public void addEmployee(Employee e) { staff.add(e); }
    public List<Employee> getStaff() { return staff; }
    public String getDeptName() { return deptName; }
}

// Service Engine
class PayrollEngine {
    private final TaxStrategy taxStrategy;
    public PayrollEngine(TaxStrategy taxStrategy) { this.taxStrategy = taxStrategy; }

    public List<PaySlip> processDepartment(Department dept) {
        List<PaySlip> slips = new ArrayList<>();
        for (Employee emp : dept.getStaff()) {
            double gross = emp.calculateGrossPay();
            double tax = taxStrategy.computeTax(gross);
            slips.add(new PaySlip(emp.getPayeeId(), gross, tax));
        }
        return slips;
    }
}

public class CapstonePayrollApp {
    public static void main(String[] args) {
        Department eng = new Department("Cloud Engineering");
        eng.addEmployee(new SalariedEmployee("E-01", "Alice", "Cloud", 6000.0));
        eng.addEmployee(new HourlyEmployee("E-02", "Bob", "Cloud", 40.0, 50.0)); // 40*40 + 10*60 = 2200

        PayrollEngine engine = new PayrollEngine(new StandardTaxStrategy());
        List<PaySlip> slips = engine.processDepartment(eng);

        for (PaySlip slip : slips) {
            System.out.println("PaySlip for " + slip.getEmployeeId() + ": Gross=$" + slip.getGrossPay() + ", Net=$" + slip.getNetPay());
        }
    }
}

