abstract class Employee {
    private String id;
    private String name;
    private String department;
    public Employee(String id, String name, String dept) {
        this.id = id; this.name = name; this.department = dept;
    }
    public String getId() { return id; }
    public abstract double calculateGrossPay();
}

class CommissionEmployee extends Employee {
    private double baseSalary;
    private double salesAmount;
    private double commissionRate;

    public CommissionEmployee(String id, String name, String dept, double base, double sales, double rate) {
        super(id, name, dept);
        this.baseSalary = base;
        this.salesAmount = sales;
        this.commissionRate = rate;
    }

    @Override
    public double calculateGrossPay() {
        return baseSalary + (salesAmount * commissionRate);
    }
}

public class Practice1 {
    public static void main(String[] args) {
        CommissionEmployee emp = new CommissionEmployee("E-03", "Sam", "Sales", 2000.0, 50000.0, 0.05);
        System.out.println("Gross: $" + emp.calculateGrossPay());
    }
}

class PaySlip {
    private final String payeeId;
    private final double gross;
    private final double tax;
    private final double net;

    public PaySlip(String payeeId, double gross, double taxRate) {
        this.payeeId = payeeId;
        this.gross = gross;
        this.tax = gross * taxRate;
        this.net = gross - this.tax;
    }

    public String getPayeeId() { return payeeId; }
    public double getGross() { return gross; }
    public double getTax() { return tax; }
    public double getNet() { return net; }

    public String getSummary() {
        return payeeId + " -> Gross: $" + gross + ", Net: $" + net;
    }
}

public class PaySlipDemo {
    public static void main(String[] args) {
        PaySlip slip = new PaySlip("EMP-55", 4000.0, 0.20);
        System.out.println(slip.getSummary());
        System.out.println("Tax deducted: $" + slip.getTax());
    }
}

import java.util.ArrayList;
import java.util.List;

interface PayableMember {
    String getName();
    double getMonthlyCost();
}

class StaffMember implements PayableMember {
    private final String name;
    private final double cost;
    public StaffMember(String name, double cost) {
        this.name = name;
        this.cost = cost;
    }
    @Override
    public String getName() { return name; }
    @Override
    public double getMonthlyCost() { return cost; }
}

class DepartmentAggregate {
    private final String name;
    private final double maxBudget;
    private final List<PayableMember> staff = new ArrayList<>();

    public DepartmentAggregate(String name, double maxBudget) {
        this.name = name;
        this.maxBudget = maxBudget;
    }

    public boolean addStaff(PayableMember m) {
        if (getTotalExpenditure() + m.getMonthlyCost() > maxBudget) {
            return false;
        }
        staff.add(m);
        return true;
    }

    public double getTotalExpenditure() {
        double sum = 0;
        for (PayableMember m : staff) sum += m.getMonthlyCost();
        return sum;
    }
}

public class DeptBudgetApp {
    public static void main(String[] args) {
        DepartmentAggregate dept = new DepartmentAggregate("DevOps", 10000.0);
        boolean added1 = dept.addStaff(new StaffMember("Alice", 6000.0));
        boolean added2 = dept.addStaff(new StaffMember("Bob", 5000.0));

        System.out.println("Added Alice: " + added1);
        System.out.println("Added Bob: " + added2);
        System.out.println("Total Expenditure: $" + dept.getTotalExpenditure());
    }
}

