class HourlyContractor {
    private double rate;
    private double hours;
    public HourlyContractor(double rate, double hours) {
        this.rate = rate;
        this.hours = hours;
    }
    public double calculateGross() {
        if (hours <= 40) {
            return hours * rate;
        }
        return (40 * rate) + ((hours - 40) * rate * 1.5);
    }
}

public class OvertimeBugDemo {
    public static void main(String[] args) {
        HourlyContractor c = new HourlyContractor(50.0, 50.0);
        System.out.println("Gross Pay: $" + c.calculateGross());
    }
}

import java.util.ArrayList;
import java.util.List;

interface PayableRecord {
    String getId();
    double computeEarnings();
}

interface TaxEngine {
    double calculateTax(double earnings);
}

class FlatTaxEngine implements TaxEngine {
    @Override
    public double calculateTax(double earnings) {
        return earnings * 0.10;
    }
}

class SalariedStaff implements PayableRecord {
    private final String id;
    private final double salary;
    public SalariedStaff(String id, double salary) {
        this.id = id;
        this.salary = salary;
    }
    @Override
    public String getId() { return id; }
    @Override
    public double computeEarnings() { return salary; }
}

class AuditedPayrollProcessor {
    private final TaxEngine taxEngine;
    public AuditedPayrollProcessor(TaxEngine taxEngine) {
        this.taxEngine = taxEngine;
    }
    public double disburseTotalNet(List<PayableRecord> records) {
        double totalNet = 0;
        for (PayableRecord r : records) {
            double gross = r.computeEarnings();
            double tax = taxEngine.calculateTax(gross);
            totalNet += (gross - tax);
        }
        return totalNet;
    }
}

public class CapstoneDisbursementApp {
    public static void main(String[] args) {
        List<PayableRecord> team = new ArrayList<>();
        team.add(new SalariedStaff("S-1", 3000.0));
        team.add(new SalariedStaff("S-2", 5000.0));

        AuditedPayrollProcessor processor = new AuditedPayrollProcessor(new FlatTaxEngine());
        double net = processor.disburseTotalNet(team);
        System.out.println("Total Net Disbursed: $" + net);
    }
}
